package com.nephh.business;
import com.nephh.common.ApiResponse;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.time.Instant;
import java.sql.Timestamp;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business")
public class TelemetryController {
 private final JdbcTemplate db;private final AccessService access;private final TelemetryService telemetry;
 public TelemetryController(JdbcTemplate db,AccessService access,TelemetryService telemetry){this.db=db;this.access=access;this.telemetry=telemetry;}
 public record Report(String messageId,String source,Instant collectedAt,Map<String,Double> values){}
 @PostMapping("/nodes/{id}/telemetry") public ApiResponse<?> report(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Report b){var a=access.actor(jwt);access.manager(a);access.node(a,id);return ApiResponse.ok(Map.of("inserted",telemetry.ingest(id,b.messageId(),b.source(),b.collectedAt(),b.values())));}
 @GetMapping("/nodes/{id}/history") public ApiResponse<?> history(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestParam(defaultValue="24") int hours,@RequestParam(required=false) String metric,@RequestParam(required=false) Instant from,@RequestParam(required=false) Instant to){var a=access.actor(jwt);access.node(a,id);if(hours<1||hours>720)bad("查询范围应在1至720小时之间");Instant end=to==null?Instant.now():to,start=from==null?end.minusSeconds(hours*3600L):from;if(!start.isBefore(end)||start.plusSeconds(720*3600L).isBefore(end))bad("查询范围最多30天");if(metric!=null&&!TelemetryService.UNITS.containsKey(metric))bad("指标不合法");return ApiResponse.ok(metric==null?db.queryForList("select * from telemetry where node_id=? and collected_at between ? and ? order by collected_at desc limit 5000",id,Timestamp.from(start),Timestamp.from(end)):db.queryForList("select * from telemetry where node_id=? and metric=? and collected_at between ? and ? order by collected_at desc limit 5000",id,metric,Timestamp.from(start),Timestamp.from(end)));}
 @PostMapping("/nodes/{id}/simulate") public ApiResponse<?> simulate(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);var node=access.node(a,id);String scenario=text(b,"scenario",30);double gas=12,temp=25;if(scenario.equals("gas"))gas=48;if(scenario.equals("heat"))temp=65;if(!Set.of("normal","gas","heat","offline").contains(scenario))bad("场景不存在");if(scenario.equals("offline")){db.update("update monitoring_node set last_seen=? where id=?",Timestamp.from(Instant.now().minusSeconds(259201)),id);telemetry.checkOffline();}else{var values=new HashMap<String,Double>(Map.of("methane",gas,"temperature",temp,"humidity",60.0,"infrared",temp+2));values.keySet().retainAll(Set.of(node.get("metrics").toString().split(",")));telemetry.ingest(id,UUID.randomUUID().toString(),"SIMULATOR",Instant.now(),values);}access.audit(a,"SIMULATE","NODE",id,null,scenario);return ApiResponse.ok(null);}
 @GetMapping("/rules") public ApiResponse<?> rules(@AuthenticationPrincipal Jwt jwt,@RequestParam long areaId){var a=access.actor(jwt);access.manager(a);access.area(a,areaId);return ApiResponse.ok(db.queryForList("select * from alarm_rule where area_id=?",areaId));}
 @PostMapping("/rules") @Transactional public ApiResponse<?> rule(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);long area=number(b,"areaId");access.area(a,area);String metric=text(b,"metric",30),severity=text(b,"severity",20);if(!TelemetryService.UNITS.containsKey(metric)||!Set.of("LOW","MEDIUM","HIGH").contains(severity))bad("指标或级别无效");double threshold=Double.parseDouble(String.valueOf(b.get("threshold")));int duration=(int)number(b,"durationSeconds");if(!Double.isFinite(threshold)||duration<0||duration>86400)bad("阈值或持续时间不合法");var before=db.queryForList("select * from alarm_rule where area_id=? and metric=?",area,metric);if(before.isEmpty())db.update("insert into alarm_rule(area_id,metric,threshold_value,duration_seconds,severity,enabled) values(?,?,?,?,?,?)",area,metric,threshold,duration,severity,Boolean.TRUE.equals(b.get("enabled")));else db.update("update alarm_rule set threshold_value=?,duration_seconds=?,severity=?,enabled=? where area_id=? and metric=?",threshold,duration,severity,Boolean.TRUE.equals(b.get("enabled")),area,metric);access.audit(a,"UPDATE","RULE",area+":"+metric,before,b);return ApiResponse.ok(null);}
 @GetMapping("/alarms") public ApiResponse<?> alarms(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);String sql="select al.*,n.code,n.area_id from alarm al join monitoring_node n on n.id=al.node_id ";return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList(sql+"order by al.id desc limit 500"):db.queryForList(sql+"join user_area u on u.area_id=n.area_id where u.user_id=? order by al.id desc limit 500",a.id()));}
 @PostMapping("/alarms/{id}/acknowledge") public ApiResponse<?> ack(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);var alarm=access.one("select * from alarm where id=?",id);access.node(a,((Number)alarm.get("node_id")).longValue());db.update("update alarm set status='ACKNOWLEDGED',acknowledged_by=?,acknowledged_at=CURRENT_TIMESTAMP,note=? where id=?",a.id(),text(b,"note",1000),id);access.audit(a,"ACKNOWLEDGE","ALARM",id,alarm,b);return ApiResponse.ok(null);}
}
